task.en:
What is wrong in the following code, assuming the Circle class has a private radius field?
```cpp
Circle c;
cout << c.radius << endl;
```

example.code:
#include <iostream>

class Circle {
public:
    Circle() : radius(1.0) {}
    explicit Circle(double newRadius) {
        setRadius(newRadius);
    }

    double getArea() const {
        return radius * radius * 3.14159;
    }

    double getRadius() const {
        return radius;
    }

    void setRadius(double newRadius) {
        radius = (newRadius >= 0.0) ? newRadius : 0.0;
    }

private:
    double radius;
};

int main() {
    Circle circle1;
    Circle circle2(5.0);

    std::cout << "The area of the circle of radius " << circle1.getRadius() 
              << " is " << circle1.getArea() << "\n";
    std::cout << "The area of the circle of radius " << circle2.getRadius() 
              << " is " << circle2.getArea() << "\n";

    circle2.setRadius(100.0);
    std::cout << "The area of the circle of radius " << circle2.getRadius() 
              << " is " << circle2.getArea() << "\n";

    // Test input validation with negative radius
    circle2.setRadius(-10.0);
    std::cout << "The area of the circle of radius " << circle2.getRadius() 
              << " is " << circle2.getArea() << "\n";

    return 0;
}

